<?php
if(PHP_SAPI!=='cli')exit(1);ob_start();require_once __DIR__.'/../koneksi.php';require_once __DIR__.'/http_form_scope.php';spp_test_assert_database_target($koneksi);require_once __DIR__.'/../includes/legacy_full.php';require_once __DIR__.'/legacy_finance_support.php';
$root=dirname(getenv('SPP_TEST_ISOLATED_INSTANCE'));$fixture=json_decode(file_get_contents($root.'/operational-fixture.json'),true);$base=getenv('SPP_TEST_BASE_URL');spp_test_assert_http_clone($base,DB_NAME);
function op_session(int $id,string $role,int $unit): string {$sid='opqa'.bin2hex(random_bytes(12));session_id($sid);session_start();$_SESSION=['admin_id'=>$id,'admin_role'=>$role,'active_unit_id'=>$unit,'csrf_legacy_import'=>str_repeat('a',64)];session_write_close();return $sid;}
function op_http(string $path,string $sid='',?array $post=null): array {global $base;$c=curl_init($base.'/'.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIE=>'PHPSESSID='.$sid,CURLOPT_TIMEOUT=>120]);if($post!==null){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,http_build_query($post));}$body=curl_exec($c);if($body===false)throw new RuntimeException(curl_error($c));$status=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return [$status,$body];}
$job=$fixture['job'];unit_set_context($koneksi,1);$payment=lf_one($koneksi,'SELECT id,owner_id FROM legacy_op_payments WHERE batch_id=? LIMIT 1',[$job]);$student=lf_one($koneksi,'SELECT student_id FROM legacy_op_owners WHERE id=?',[$payment['owner_id']]);$paths=['legacy_operational_review.php?id='.$job,'legacy_correction.php?kind=payment&id='.$payment['id'],'legacy_tariff.php?student='.$student['student_id']];
foreach($paths as $path)lft_assert(in_array(op_http($path)[0],[302,403],true),'Anonymous accepted');$sessions=[];foreach([1,2,3] as $unit)$sessions[$unit]=op_session($fixture['actor'],'super_admin',$unit);
$before=lop_working_digest($koneksi,$job);foreach(['groups','people','components','savings','confirm'] as $section){[$status,$html]=op_http('legacy_operational_review.php?id='.$job.'&section='.$section.'&person=212200001',$sessions[1]);lft_assert($status===200&&!str_contains($html,'Fatal error')&&!str_contains($html,'Warning:'),'Review panel '.$section.' failed '.$status);}
foreach($paths as $path){[$s,$html]=op_http($path,$sessions[1]);lft_assert($s===200&&!str_contains($html,'Fatal error'),'Authorized page failed');lft_assert(in_array(op_http($path,$sessions[2])[0],[403,404,409],true),'Unit leak');}
$all=op_session($fixture['actor'],'super_admin',0);lft_assert(op_http('legacy_operational_review.php?id='.$job,$all)[0]===200,'All-unit read denied');lft_assert(op_http('legacy_operational_review.php?id='.$job,$all,['action'=>'simulate','id'=>$job,'csrf_token'=>str_repeat('a',64)])[0]===409,'All-unit mutation accepted');
$inactiveName='op_inactive_'.bin2hex(random_bytes(6));lf_query($koneksi,'INSERT INTO admin(username,password,nama,role,unit_id,is_active) SELECT ?,password,\'Inactive isolated fixture\',role,unit_id,0 FROM admin WHERE id=?',[$inactiveName,$fixture['actor']]);$inactive=(int)$koneksi->insert_id;try{$inactiveSession=op_session($inactive,'super_admin',1);foreach($paths as $path)lft_assert(in_array(op_http($path,$inactiveSession)[0],[302,403],true),'Inactive actor accepted');}finally{lf_query($koneksi,'DELETE FROM admin WHERE id=? AND username=?',[$inactive,$inactiveName]);}
foreach(['admin','kasir','bendahara'] as $role){$a=lf_one($koneksi,'SELECT id,unit_id FROM admin WHERE role=? AND is_active=1 LIMIT 1',[$role]);if(!$a)continue;$sid=op_session($a['id'],$role,(int)$a['unit_id']);foreach($paths as $path)lft_assert(in_array(op_http($path,$sid)[0],[302,403],true),'Role accepted '.$role);}
foreach($paths as $path)lft_assert(op_http($path,$sessions[1],['action'=>'save','csrf_token'=>'wrong'])[0]===403,'CSRF accepted');lft_assert(op_http('legacy_operational_review.php?section[]=x',$sessions[1])[0]===400,'Malformed filter accepted');lft_assert(op_http('legacy_import_api.php?action=full_status&id='.$job,$sessions[1])[0]===200,'Compatible status API failed');unit_set_context($koneksi,1);lft_assert(lop_working_digest($koneksi,$job)===$before,'UI or rejected POST mutated working data');
file_put_contents($root.'/operational-browser.json',lf_json(['base'=>$base,'job'=>$job,'sessions'=>$sessions,'payment'=>$payment['id'],'student'=>$student['student_id'],'owner'=>$payment['owner_id']]));echo "PASS: server-rendered panels, compatible status, anonymous/role/unit checks, CSRF and no mutations.\n";
